import {analyze,demo,today,shift,days,dateValid,addMove,parseCSV,importRows,norm} from './engine.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:1}).format(n),money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n),br=d=>d?d.split('-').reverse().join('/'):'Não informada',uid=()=>crypto.randomUUID();
const KEY='agroalerta-v1',SET='agroalerta-settings-v1';let db,settings={window:30,urgent:7,expiry:30,excess:120},storageWarning='';
try{db=JSON.parse(localStorage.getItem(KEY))||demo();settings={...settings,...JSON.parse(localStorage.getItem(SET)||'{}')};}catch{db=demo();storageWarning='Não foi possível carregar o armazenamento. Exporte backups.';}
let report=analyze(db,today(),settings),page='overview';
function save(){try{localStorage.setItem(KEY,JSON.stringify(db));localStorage.setItem(SET,JSON.stringify(settings));}catch{toast('Não foi possível salvar no navegador. Exporte o backup antes de fechar.');}report=analyze(db,today(),settings);render();}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',5500);}
function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);}
const priorities=['Atenção imediata','Acompanhar','Revisar','Normal'];
function badge(n){return `<span class="badge ${n===0?'high':n===1?'medium':''}">${priorities[n]}</span>`;}
function alertCard(a){const p=db.products.find(x=>x.id===a.productId);return `<article class="alert ${a.priority===0?'high':a.priority===1?'medium':''}"><div class="alert-head"><h3>${esc(p.name)} <span style="font-weight:400">· ${esc(a.title)}</span></h3>${badge(a.priority)}</div><p>${esc(a.why)}</p><p class="action">↳ ${esc(a.action)}</p><button data-detail="${esc(p.id)}">Ver histórico e critérios →</button></article>`;}
function metric(label,value,hint,icon){return `<div class="metric"><span class="metric-icon">${icon}</span><div class="label">${label}</div><strong>${value}</strong><small>${hint}</small></div>`;}
function panel(title,sub,body,action=''){return `<section class="panel"><div class="panel-title"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>${body}</section>`;}
const empty=text=>`<div class="empty">${text}</div>`;
function overview(){const alerts=report.alerts,critical=report.products.filter(p=>p.priority===0).length,expiry=report.products.filter(p=>p.alerts.some(a=>a.kind==='expiry')).length;const tops=[...report.products].sort((a,b)=>b.value-a.value).slice(0,5);const max=Math.max(1,...tops.map(p=>p.value));return `<section class="hero"><div><div class="eyebrow">DO REGISTRO À DECISÃO</div><h2>${critical?`${critical} ${critical===1?'produto merece':'produtos merecem'} sua atenção hoje.`:'Um olhar atento para cada insumo.'}</h2><p>Antecipe faltas, acompanhe os lotes e entenda para onde vai o valor do seu estoque.</p><button data-go="alerts">Conferir minhas prioridades →</button></div><div class="hero-art" aria-hidden="true">↗</div></section><div class="metrics">${metric('Produtos cadastrados',db.products.length,'Categorias e unidades separadas','▤')}${metric('Atenção imediata',critical,'Produtos com pelo menos um alerta alto','!')}${metric('Risco de vencimento',expiry,'Produtos com lotes em atenção','◷')}${metric('Valor conhecido',money(report.value),report.unknown?`${report.unknown} lote(s) sem preço; total parcial`:'Custo dos lotes com saldo','R$')}</div><div class="grid">${panel('O que precisa de atenção?','Prioridades com um motivo e uma próxima ação.',alerts.slice(0,4).map(alertCard).join('')||empty('Nenhum alerta pelos critérios atuais.'),'<button class="text-link" data-go="alerts">Ver todos →</button>')}${panel('Onde está o valor do estoque?','Custo de aquisição dos lotes restantes.',tops.map(p=>`<div class="bar-row"><div class="bar-top"><b>${esc(p.name)}</b><span>${money(p.value)}</span></div><div class="track"><div class="fill" style="width:${p.value/max*100}%"></div></div><small>${fmt(p.physical)} ${esc(p.unit)} em estoque${p.unknown?' · preço parcial':''}</small></div>`).join('')||empty('Cadastre produtos para começar.'))}</div><div class="note">ⓘ Referência: ${br(today())}. Cobertura usa ${settings.window} dias de histórico. ${db.source==='simulados'?'Você está explorando dados simulados, não a base oficial.':'Origem dos dados: '+esc(db.source)+'.'} Os registros são locais a este navegador.</div>`;}
function alertsPage(){return `<div class="toolbar"><input id="search" placeholder="Buscar produto ou situação…" aria-label="Buscar alertas"><select id="priority-filter" aria-label="Prioridade"><option value="all">Todas as prioridades</option><option value="0">Atenção imediata</option><option value="1">Acompanhar</option><option value="2">Revisar</option></select></div><div id="alert-list"></div>`;}
function filterAlerts(){const query=norm($('#search').value),priority=$('#priority-filter').value;const list=report.alerts.filter(a=>(priority==='all'||a.priority===Number(priority))&&norm(db.products.find(p=>p.id===a.productId).name+' '+a.title+' '+a.why).includes(query));$('#alert-list').innerHTML=list.map(alertCard).join('')||empty('Nenhum alerta encontrado para este filtro.');}
function stockPage(){return panel('Todos os insumos','Saldo físico e saldo utilizável por produto.',`<div class="toolbar"><input id="search" placeholder="Buscar produto…" aria-label="Buscar estoque"><select id="category-filter" aria-label="Categoria"><option value="all">Todas as categorias</option>${[...new Set(db.products.map(p=>p.category))].map(c=>`<option>${esc(c)}</option>`).join('')}</select><button id="new-product">＋ Cadastrar produto</button></div><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Estoque utilizável</th><th>Cobertura</th><th>Valor conhecido</th><th>Situação</th></tr></thead><tbody id="stock-rows"></tbody></table></div>`);}
function filterStock(){const q=norm($('#search').value),c=$('#category-filter').value;const list=report.products.filter(p=>norm(p.name).includes(q)&&(c==='all'||p.category===c));$('#stock-rows').innerHTML=list.map(p=>`<tr><td><button data-detail="${esc(p.id)}"><b>${esc(p.name)}</b><small>${esc(p.category)}</small></button></td><td><b>${fmt(p.usable)} ${esc(p.unit)}</b><small>Mínimo ${fmt(p.minimum)} · físico ${fmt(p.physical)}</small></td><td>${p.coverage===null?'Indisponível':fmt(p.coverage)+' dias'}<small>${!p.enough?'Histórico limitado':p.rate===0?'Sem consumo recente':fmt(p.rate)+' '+esc(p.unit)+'/dia'}</small></td><td>${money(p.value)}${p.unknown?'<small>Valor parcial · preço ausente</small>':''}</td><td>${badge(p.priority)}</td></tr>`).join('')||'<tr><td colspan="5">Nenhum produto encontrado.</td></tr>';}
function movesPage(){return panel('Histórico de movimentações','Cada atualização recalcula saldos e alertas.',`<div class="toolbar"><input id="search" placeholder="Buscar produto, destino ou responsável…" aria-label="Buscar movimentações"><select id="type-filter" aria-label="Tipo"><option value="all">Entradas e saídas</option><option value="entrada">Entradas</option><option value="saida">Saídas</option></select><button id="export-csv">↓ Exportar CSV</button></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Produto / lote</th><th>Tipo</th><th>Quantidade</th><th>Destino</th><th>Responsável</th></tr></thead><tbody id="move-rows"></tbody></table></div>`);}
function filterMoves(){const q=norm($('#search').value),type=$('#type-filter').value;const list=[...db.moves].sort((a,b)=>b.date.localeCompare(a.date)).filter(m=>{const p=db.products.find(p=>p.id===m.productId);return (type==='all'||type===m.type)&&norm(p.name+' '+m.destination+' '+m.responsible).includes(q);});$('#move-rows').innerHTML=list.map(m=>{const p=db.products.find(p=>p.id===m.productId),l=db.lots.find(l=>l.id===m.lotId);return `<tr><td>${br(m.date)}</td><td><b>${esc(p.name)}</b><small>${esc(l.code)}</small></td><td><span class="badge ${m.type==='saida'?'medium':''}">${m.type==='entrada'?'↗ Entrada':'↘ Saída'}</span></td><td>${fmt(m.quantity)} ${esc(p.unit)}</td><td>${esc(m.destination)||'—'}</td><td>${esc(m.responsible)||'—'}</td></tr>`;}).join('')||'<tr><td colspan="6">Nenhuma movimentação encontrada.</td></tr>';}
function importPage(){return `<div class="note">A base oficial ainda não foi fornecida nesta conversa. CSVs externos precisam seguir o modelo abaixo. Toda importação é validada antes de salvar; a mesma base não é adicionada novamente.</div>${panel('Importar movimentações','CSV em UTF-8, separado por ponto e vírgula ou vírgula.',`<form id="import-form"><div class="form-grid"><div class="field"><label for="csv-file">Arquivo CSV</label><input id="csv-file" type="file" accept=".csv,text/csv" required></div><div class="field"><label for="origin">Origem da base</label><select id="origin"><option value="oficiais">Dados oficiais do desafio</option><option value="simulados">Dados simulados</option><option value="propriedade">Dados de propriedade</option></select></div></div><p style="font-size:12px;margin-top:16px">O arquivo será incorporado ao estoque atual. Para trabalhar apenas com a base oficial, exporte o backup e inicie uma base vazia antes.</p><div class="form-actions"><button type="button" id="template" class="ghost">↓ Baixar modelo CSV</button><button class="primary" type="submit">Validar e importar</button></div><div class="form-error" id="import-result" role="status"></div></form>`)}${panel('Formato e qualidade dos registros','Uma linha por movimentação. Inclua a entrada inicial de cada lote.',`<div class="mono">id;produto;categoria;unidade;minimo;lote;tipo;data;quantidade;preco;validade;destino;responsavel</div><p style="font-size:12px;margin-top:15px">Datas: AAAA-MM-DD. Tipos: entrada ou saida. Preço: custo unitário do lote; vazio significa desconhecido. Validade pode ficar vazia. Mantenha o mesmo preço e validade nas linhas do mesmo lote. Use códigos distintos para aquisições com preços diferentes. Não há conversão automática de unidades.</p><p style="font-size:12px">O ID estável é recomendado. Sem ID, linhas com mesmo produto, lote, tipo, data, quantidade, destino e responsável são consideradas duplicadas; duas retiradas legítimas idênticas precisam de IDs distintos.</p>`)}${panel('Backup e ambiente de demonstração','As alterações são salvas localmente neste navegador.',`<div class="stack-buttons"><button id="restore">↑ Restaurar backup JSON</button><button id="load-demo">Carregar demonstração</button><button id="clear-data" class="danger">Iniciar base vazia</button></div><input type="file" id="backup-file" accept=".json" hidden><p style="font-size:12px;margin-top:13px">A restauração e a troca de base substituem os registros atuais, após confirmação. O backup contém produtos, lotes, movimentações e critérios.</p>`)} `;}
function methodsPage(){return `${panel('Critérios transparentes','Regras propostas pela equipe, ajustáveis e verificáveis.',`<form id="settings-form"><div class="settings">${[['window','Janela de consumo (dias)',7,90],['urgent','Falta iminente (dias)',1,30],['expiry','Validade próxima (dias)',1,180],['excess','Possível excesso (dias)',30,365]].map(([key,label,min,max])=>`<div class="field"><label for="${key}">${label}</label><input id="${key}" name="${key}" type="number" min="${min}" max="${max}" step="1" value="${settings[key]}" required></div>`).join('')}</div><div class="form-actions"><button class="primary">Salvar e reanalisar</button></div></form>`)}${panel('Como o AgroAlerta analisa seu estoque','Os resultados apoiam a decisão do responsável.',[
 ['Saldo e unidades','Saldo físico = entradas − saídas por lote. Saldo utilizável exclui lotes vencidos. Unidades diferentes não são somadas; produtos com mesma descrição e unidades distintas permanecem separados.'],
 ['Consumo e cobertura',`Consumo médio = saídas dos últimos ${settings.window} dias ÷ ${settings.window}, incluindo dias sem retirada. Cobertura = saldo utilizável ÷ consumo médio. Exigimos ${settings.window} dias de histórico e ao menos 3 saídas recentes. Sem consumo ou histórico suficiente, a previsão fica indisponível. A data da primeira movimentação é uma referência; a equipe deve confirmar que o histórico está completo.`],
 ['Vencimento por lote','Considera consumo constante e lotes em ordem de vencimento. O consumo projetado é alocado primeiro aos lotes que vencem antes, sem contá-lo duas vezes. Lotes vencidos geram prioridade alta. Ausência de validade não significa ausência de risco.'],
 ['Retiradas incomuns','Uma saída maior que 3 vezes a mediana de pelo menos 5 saídas anteriores nos 90 dias precedentes gera alerta de conferência. Comparamos apenas o mesmo produto e unidade; uma retirada grande pode ser legítima.'],
 ['Consumo crescente','Com histórico de duas janelas completas, aumento superior a 50% no total retirado gera alerta. Quando o consumo anterior é zero, não calculamos crescimento percentual.'],
 ['Valor, excesso e preços',`Valor conhecido = saldo do lote × custo unitário de aquisição. Preços ausentes deixam o total parcial. Cobertura acima de ${settings.excess} dias indica possível excesso. Ausência de retirada por 60 dias indica item parado, sem concluir que é desnecessário. Aumento de custo acima de 20% entre os dois últimos lotes adquiridos exige conferência.`],
 ['Prioridades','Alta: falta de estoque utilizável, lote vencido, cobertura ou vencimento dentro da janela de urgência. Média: mínimo, vencimento, consumo crescente e anomalias. Revisão: excesso, itens parados e preços. Um produto pode ter vários alertas; o painel conta produtos, a central mostra situações.'],
 ['Limitações e autoria','Não usa previsão agronômica, calendário de safra ou prazo real de fornecedores. Nomes semelhantes não são unidos automaticamente. A importação agrupa apenas nome normalizado, categoria e unidade equivalentes. Dados simulados são identificados. Código e documentação foram desenvolvidos com apoio de ChatGPT/Codex; a equipe deve revisar, compreender, validar com usuários e declarar esse uso na entrega.']
 ].map(([h,p])=>`<div class="method"><h3>${h}</h3><p>${p}</p></div>`).join(''))}`;}
const pages={overview:['Seu estoque, sob controle.','Decisões mais claras. Menos surpresas na sua propriedade.',overview],alerts:['Uma prioridade de cada vez.','Entenda o problema, o motivo e a próxima ação.',alertsPage],stock:['Cada insumo no seu lugar.','Saldo, validade e cobertura em uma visão organizada.',stockPage],moves:['O campo em movimento.','Registre entradas e saídas. A análise acompanha você.',movesPage],import:['Seus dados, novas respostas.','Importe registros, preserve o histórico e reanalise.',importPage],methods:['Você entende cada alerta.','Critérios claros para apoiar decisões responsáveis.',methodsPage]};
function render(){page=location.hash.slice(1)||'overview';if(!pages[page])page='overview';const [title,sub,fn]=pages[page];$('#page-title').textContent=title;$('#page-subtitle').textContent=sub;$('#crumb').textContent=$(`nav a[data-page="${page}"] span`).textContent;document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));$('#source-tag').textContent=db.source==='simulados'?'DADOS SIMULADOS':db.source==='mista'?'BASE MISTA':db.source==='vazia'?'BASE VAZIA':db.source==='oficiais'?'DADOS OFICIAIS':'DADOS DA PROPRIEDADE';$('#alert-count').textContent=report.alerts.length;$('#content').innerHTML=fn();
 if(page==='alerts'){filterAlerts();$('#search').oninput=filterAlerts;$('#priority-filter').onchange=filterAlerts;}
 if(page==='stock'){filterStock();$('#search').oninput=filterStock;$('#category-filter').onchange=filterStock;$('#new-product').onclick=productModal;}
 if(page==='moves'){filterMoves();$('#search').oninput=filterMoves;$('#type-filter').onchange=filterMoves;$('#export-csv').onclick=exportCSV;}
 if(page==='import'){bindImport();}
 if(page==='methods')$('#settings-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);for(const k of Object.keys(settings))settings[k]=Number(f.get(k));save();toast('Critérios atualizados. Estoque reanalisado.');};
}
function modal(title,body){$('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button data-close aria-label="Fechar">×</button></div>${body}`;$('#modal').showModal();}
function field(label,name,type='text',value='',extra=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function productModal(){modal('Cadastrar um insumo',`<form id="product-form"><div class="form-grid">${field('Nome do produto','name','text','','required maxlength="100"')}${field('Categoria','category','text','','required maxlength="60"')}<div class="field"><label for="f-unit">Unidade</label><select name="unit" id="f-unit">${['kg','L','un','m','g','mL'].map(u=>`<option>${u}</option>`).join('')}</select></div>${field('Estoque mínimo','minimum','number',0,'required min="0" step="any"')}${field('Código do lote inicial','code','text','','required maxlength="60"')}${field('Quantidade inicial','quantity','number',0,'required min="0" step="any"')}${field('Custo unitário (opcional)','price','number','','min="0" step="any"')}${field('Validade (opcional)','expiry','date')}</div><div class="form-error" id="form-error"></div><div class="form-actions"><button type="button" data-close class="ghost">Cancelar</button><button class="primary">Cadastrar produto</button></div></form>`);$('#product-form').onsubmit=e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target)),p={id:uid(),name:f.name.trim(),category:f.category.trim(),unit:f.unit,minimum:Number(f.minimum)};if(!p.name||!p.category)throw Error('Nome e categoria são obrigatórios.');if(db.products.some(x=>norm(x.name)===norm(p.name)&&norm(x.unit)===norm(p.unit)&&norm(x.category)===norm(p.category)))throw Error('Produto já cadastrado. Registre uma entrada ou um novo lote.');const l={id:uid(),productId:p.id,code:f.code.trim(),price:f.price===''?null:Number(f.price),expiry:f.expiry||null};if(!l.code)throw Error('Informe um código de lote válido.');if(l.expiry&&!dateValid(l.expiry))throw Error('Validade inválida.');const next=structuredClone(db);next.products.push(p);next.lots.push(l);if(Number(f.quantity)>0)addMove(next,{id:uid(),productId:p.id,lotId:l.id,type:'entrada',quantity:Number(f.quantity),date:today(),destination:'Estoque inicial',responsible:'Cadastro manual'});db=next;$('#modal').close();save();toast('Produto cadastrado e estoque reanalisado.');}catch(err){$('#form-error').textContent=err.message;}};}
function moveModal(){if(!db.products.length){productModal();return;}modal('Nova movimentação',`<form id="move-form"><div class="form-grid"><div class="field"><label for="f-productId">Produto</label><select id="f-productId" name="productId">${db.products.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} (${esc(p.unit)})</option>`).join('')}</select></div><div class="field"><label for="f-type">Tipo</label><select id="f-type" name="type"><option value="saida">Saída</option><option value="entrada">Entrada</option></select></div><div class="field full"><label for="f-lotId">Lote</label><select id="f-lotId" name="lotId"></select></div><div id="new-lot-fields" class="field full" hidden><div class="form-grid">${field('Código do novo lote','code')}${field('Custo unitário (opcional)','price','number','','min="0" step="any"')}${field('Validade (opcional)','expiry','date')}</div></div>${field('Quantidade na unidade do produto','quantity','number','','required min="0.000001" step="any"')}${field('Data','date','date',today(),`required max="${today()}"`)}${field('Destino / origem','destination','text','','required maxlength="100"')}${field('Responsável','responsible','text','','required maxlength="100"')}</div><div class="form-error" id="form-error"></div><div class="form-actions"><button data-close type="button" class="ghost">Cancelar</button><button class="primary">Salvar e reanalisar</button></div></form>`);
 const update=()=>{const p=report.products.find(p=>p.id===$('#f-productId').value);$('#f-lotId').innerHTML=p.lots.map(l=>`<option value="${esc(l.id)}">${esc(l.code)} · ${fmt(l.balance)} ${esc(p.unit)}${l.expiry?' · validade '+br(l.expiry):''}</option>`).join('')+($('#f-type').value==='entrada'?'<option value="new">＋ Criar novo lote</option>':'');$('#new-lot-fields').hidden=true;};update();$('#f-productId').onchange=update;$('#f-type').onchange=update;$('#f-lotId').onchange=()=>$('#new-lot-fields').hidden=$('#f-lotId').value!=='new';
 $('#move-form').onsubmit=e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target)),next=structuredClone(db);if(!f.destination.trim()||!f.responsible.trim())throw Error('Destino e responsável não podem conter apenas espaços.');let lotId=f.lotId;if(lotId==='new'){if(!f.code.trim())throw Error('Informe o código do lote.');if(next.lots.some(l=>l.productId===f.productId&&norm(l.code)===norm(f.code)))throw Error('Código de lote já existe.');lotId=uid();next.lots.push({id:lotId,productId:f.productId,code:f.code.trim(),price:f.price===''?null:Number(f.price),expiry:f.expiry||null});}addMove(next,{id:uid(),productId:f.productId,lotId,type:f.type,quantity:Number(f.quantity),date:f.date,destination:f.destination.trim(),responsible:f.responsible.trim()});db=next;$('#modal').close();save();toast('Movimentação salva. Saldos e alertas atualizados.');}catch(err){$('#form-error').textContent=err.message;}};
}
function detail(id){const p=report.products.find(p=>p.id===id);const amounts=Array.from({length:6},(_,i)=>{const start=shift(today(),-29+i*5),end=shift(start,4);return p.outs.filter(m=>m.date>=start&&m.date<=end).reduce((s,m)=>s+m.quantity,0);});const max=Math.max(1,...amounts);modal(esc(p.name),`<p>${esc(p.category)} · Unidade ${esc(p.unit)}</p><div class="kpi-inline" style="margin-top:20px"><div><small>Utilizável</small><strong>${fmt(p.usable)} ${esc(p.unit)}</strong></div><div><small>Cobertura</small><strong>${p.coverage===null?'—':fmt(p.coverage)+' dias'}</strong></div><div><small>Valor conhecido</small><strong>${money(p.value)}</strong></div></div><div class="note">${p.coverage!==null?`Saídas: ${fmt(p.consumed)} ${esc(p.unit)} em ${settings.window} dias. Média: ${fmt(p.rate)} ${esc(p.unit)}/dia. Cobertura: ${fmt(p.usable)} ÷ ${fmt(p.rate)} ≈ ${fmt(p.coverage)} dias.`:p.enough?'Sem consumo recente: cobertura indisponível.':`Histórico limitado: ${p.historyDays} dias desde o primeiro registro; ${p.recent.length} saídas recentes. Exigimos janela completa de ${settings.window} dias e 3 saídas.`} Consumo sazonal pode alterar a previsão.</div><h3>Consumo nos últimos 30 dias (${esc(p.unit)})</h3><div class="chart">${amounts.map(a=>`<div class="chart-col" style="height:${Math.max(2,a/max*100)}%"><span>${fmt(a)}</span></div>`).join('')}</div><div class="chart-labels">${amounts.map((a,i)=>`<span>${br(shift(today(),-29+i*5)).slice(0,5)}</span>`).join('')}</div><h3 style="margin-top:25px">Lotes e validade</h3><div class="table-wrap"><table><thead><tr><th>Lote</th><th>Saldo físico</th><th>Validade</th><th>Custo/un.</th></tr></thead><tbody>${p.lots.map(l=>`<tr><td>${esc(l.code)}</td><td>${fmt(l.balance)} ${esc(p.unit)}</td><td>${br(l.expiry)}</td><td>${l.price===null?'Desconhecido':money(l.price)}</td></tr>`).join('')}</tbody></table></div><h3 style="margin-top:23px">Alertas e próximos passos</h3>${p.alerts.map(a=>`<div class="alert"><h3>${esc(a.title)}</h3><p>${esc(a.why)}</p><p class="action">${esc(a.action)}</p></div>`).join('')||'<p>Nenhum alerta para os critérios atuais.</p>'}<div class="form-actions"><button class="primary" data-close>Entendi</button></div>`);}
function csvText(){const header=['id','produto','categoria','unidade','minimo','lote','tipo','data','quantidade','preco','validade','destino','responsavel'];const cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';return [header.join(';'),...db.moves.map(m=>{const p=db.products.find(p=>p.id===m.productId),l=db.lots.find(l=>l.id===m.lotId);return [m.id,p.name,p.category,p.unit,p.minimum,l.code,m.type,m.date,m.quantity,l.price,l.expiry,m.destination,m.responsible].map(cell).join(';');})].join('\r\n');}
function exportCSV(){download('agroalerta-movimentacoes.csv','\uFEFF'+csvText(),'text/csv;charset=utf-8');}
function validateBackup(raw){const obj=raw.data||raw;if(obj.version!==1||!Array.isArray(obj.products)||!Array.isArray(obj.lots)||!Array.isArray(obj.moves))throw Error('Formato de backup inválido.');if(!['simulados','oficiais','propriedade','mista','vazia'].includes(obj.source))throw Error('Origem do backup inválida.');
 for(const list of [obj.products,obj.lots,obj.moves]){const ids=new Set();for(const x of list){if(typeof x.id!=='string'||!x.id||ids.has(x.id))throw Error('IDs inválidos ou duplicados.');ids.add(x.id);}}
 for(const p of obj.products)if(!p.name||!p.category||!p.unit||!Number.isFinite(p.minimum)||p.minimum<0)throw Error('Produto inválido no backup.');
 for(const l of obj.lots)if(!obj.products.some(p=>p.id===l.productId)||!l.code||(l.price!==null&&(!Number.isFinite(l.price)||l.price<0))||(l.expiry!==null&&!dateValid(l.expiry)))throw Error('Lote inválido no backup.');
 const next={...obj,moves:[]};for(const m of [...obj.moves].sort((a,b)=>a.date.localeCompare(b.date)||(a.type==='entrada'?-1:1)))addMove(next,m);
 return next;}
function bindImport(){
 $('#template').onclick=()=>download('modelo-agroalerta.csv','\uFEFFid;produto;categoria;unidade;minimo;lote;tipo;data;quantidade;preco;validade;destino;responsavel\r\nexemplo-entrada;Produto exemplo;Categoria exemplo;kg;20;LOTE-01;entrada;'+today()+';100;5;;Estoque inicial;Responsável\r\n','text/csv;charset=utf-8');
 $('#import-form').onsubmit=async e=>{e.preventDefault();try{const file=$('#csv-file').files[0];if(file.size>5*1024*1024)throw Error('Use arquivos de até 5 MB.');const result=importRows(db,parseCSV(await file.text()),$('#origin').value);db=result.db;save();$('#import-result').style.color='var(--green)';$('#import-result').textContent=`${result.imported} movimentações importadas; ${result.skipped} duplicadas ignoradas. ${result.warnings.join(' ')}`;toast('Importação concluída. Análises atualizadas.');}catch(err){$('#import-result').textContent=err.message;}};
 $('#clear-data').onclick=()=>{if(confirm('Iniciar base vazia? Os registros atuais serão substituídos. Exporte um backup antes.')){db={version:1,source:'vazia',products:[],lots:[],moves:[]};save();toast('Base vazia pronta para os dados oficiais.');}};
 $('#load-demo').onclick=()=>{if(confirm('Substituir os registros atuais pelos dados simulados? Exporte um backup antes.')){db=demo();save();toast('Demonstração carregada com dados simulados.');}};
 $('#restore').onclick=()=>$('#backup-file').click();$('#backup-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('Backup maior que 5 MB.');const raw=JSON.parse(await file.text()),next=validateBackup(raw);if(!confirm('Restaurar este backup e substituir os registros atuais?'))return;db=next;if(raw.settings)for(const [k,min,max] of [['window',7,90],['urgent',1,30],['expiry',1,180],['excess',30,365]]){const n=raw.settings[k];if(Number.isInteger(n)&&n>=min&&n<=max)settings[k]=n;}save();toast('Backup restaurado e estoque reanalisado.');}catch(err){toast('Backup não restaurado: '+err.message);}};
}
$('#new-move').onclick=moveModal;$('#backup').onclick=()=>download('agroalerta-backup-'+today()+'.json',JSON.stringify({data:db,settings,exportedAt:new Date().toISOString()},null,2));
document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close)$('#modal').close();const go=e.target.closest('[data-go]');if(go)location.hash=go.dataset.go;const d=e.target.closest('[data-detail]');if(d)detail(d.dataset.detail);});
window.addEventListener('hashchange',render);render();if(storageWarning)toast(storageWarning);
